INSERT INTO assunto(disciplina_id,nome,slug,descricao,ordem) SELECT id,'Complemento opcional · Funções de várias variáveis','base_multivariavel','Complemento opcional criado com IA, fora da cobrança e dos simulados padrão.',8 FROM disciplina WHERE slug='calculo_para_computacao_2' ON CONFLICT(disciplina_id,slug) DO NOTHING;
INSERT INTO material(disciplina_id,assunto_id,titulo,descricao,tipo,referencia_externa,fonte_monitor_virtual,disponivel_para_pratica,autorizacao_professor) SELECT d.id,(SELECT a.id FROM assunto a WHERE a.disciplina_id=d.id AND a.slug='base_multivariavel'),'funçoes cde duas variaveis','Complemento amplo criado com IA e fornecido pelo aluno. Não é conteúdo cobrado pelo professor.','RESUMO','local:materiais_academicos/periodo_03/calculo_para_computacao_2/funçoes cde duas variaveis.pdf',TRUE,FALSE,FALSE FROM disciplina d WHERE slug='calculo_para_computacao_2' AND NOT EXISTS(SELECT 1 FROM material m WHERE m.disciplina_id=d.id AND m.referencia_externa='local:materiais_academicos/periodo_03/calculo_para_computacao_2/funçoes cde duas variaveis.pdf');
INSERT INTO material(disciplina_id,assunto_id,titulo,descricao,tipo,referencia_externa,fonte_monitor_virtual,disponivel_para_pratica,autorizacao_professor) SELECT d.id,NULL,'Guia de Integrais - NEURON','Apoio autoral NEURON com IA. Não é material nem prova oficial do professor.','RESUMO','local:materiais_academicos/periodo_03/calculo_para_computacao_2/Guia de Integrais - NEURON.pdf',TRUE,FALSE,FALSE FROM disciplina d WHERE slug='calculo_para_computacao_2' AND NOT EXISTS(SELECT 1 FROM material m WHERE m.disciplina_id=d.id AND m.referencia_externa='local:materiais_academicos/periodo_03/calculo_para_computacao_2/Guia de Integrais - NEURON.pdf');
